-- Emitted by pass.lean in `formal.lean.mode=verified_compiler`.
-- The model comes from the verified compiler; the checks and theorems below
-- instantiate its generic correctness and all-fire compatibility results.
-- by `Compiler.compileDesign_correct`.  Slots are dense: sources occupy
-- 0..3 and node i occupies 4+i.
import LeanSemanticPrimitives.Compiler.CompileDesign

set_option maxRecDepth 1000000
set_option maxHeartbeats 0

open Compiler

def tiny_ram_designCert : DesignCert :=
  {
    sources  := #[
        SourceDesc.memImg 0 2 8
      , SourceDesc.const 8 ((Int.ofNat 171))
      , SourceDesc.input 0 2
      , SourceDesc.input 1 2
      ]
    nodes    := #[
        { op := LGraphOp.Op_Or, width := 2, deps := #[2], origin := 1000000001 }
      , { op := LGraphOp.Op_Or, width := 2, deps := #[3], origin := 1000000002 }
      , { op := LGraphOp.Op_MemRead, width := 8, deps := #[0, 4, 5], origin := 1000000003 }
      , { op := LGraphOp.Op_Or, width := 2, deps := #[2], origin := 1000000004 }
      , { op := LGraphOp.Op_Or, width := 8, deps := #[1], origin := 1000000006 }
      , { op := LGraphOp.Op_Or, width := 1, deps := #[3], origin := 1000000007 }
      , { op := LGraphOp.Op_MemWrite, width := 8, deps := #[0, 7, 8, 9], origin := 1000000008 }
      ]
    outputs  := #[
        { slot := 6, width := 8 }
      ]
    flops    := #[]
    memories := #[
        { aw := 2, dw := 8, nextImg := 10, clock := 1 }
      ]
  }

/-- Compile-and-run.  The model IS the verified compiler applied to this
certificate -- there is no separately emitted model to disagree with it. -/
def tiny_ram_step : RuntimeInput → RuntimeState → RuntimeResult :=
  compileAndRun tiny_ram_designCert (allEdges tiny_ram_designCert)

/-- Compiler acceptance, independent of clock-bound well-formedness.

`native_decide`, not `.get!`: a compile failure is a BUILD failure rather
than a runtime panic with the hypothesis left undischarged.  (`decide` is
not usable -- `Array.map` is not kernel-reducible.) -/
theorem tiny_ram_compiles : compilesOk tiny_ram_designCert = true := by
  native_decide

#print axioms tiny_ram_compiles

/-- Declared clock bounds, checked independently of compiler acceptance. -/
theorem tiny_ram_clock_bounds :
    (∀ f ∈ tiny_ram_designCert.flops, f.clock < tiny_ram_designCert.clocks.size) ∧
    (∀ m ∈ tiny_ram_designCert.memories, m.clock < tiny_ram_designCert.clocks.size) := by
  native_decide
